mapper.select:
SELECT id, batch_id, org_id, kjyear, kjmoth, kjyear_month, report_type, code, value_type, result_value, data_source, create_time
FROM t_report_result

    AND org_id = #{orgId}
    AND kjyear_month = #{kjyearMonth}
    AND report_type = #{reportType}
    AND data_source = #{dataSource}

ORDER BY report_type, code, value_type

SELECT kjyear_month, code, value_type, result_value
FROM t_report_result
WHERE org_id = #{orgId} AND code = #{code}
AND value_type = #{valueType}

    AND kjyear_month IN
    #{m}

ORDER BY kjyear_month

SELECT kjyear_month, code, value_type, result_value
FROM t_report_result
WHERE org_id = #{orgId} AND kjyear_month = #{kjyearMonth}
AND value_type = #{valueType}

    AND code IN
    #{c}

ORDER BY code

SELECT kjyear_month AS kjyear_month, COUNT(1) AS cnt, MAX(create_time) AS create_time
FROM t_report_result

    AND org_id = #{orgId}
    AND report_type = #{reportType}

GROUP BY kjyear_month
ORDER BY kjyear_month DESC
